import type { ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "../../lib/cn";

/**
 * 单词本的翻页机：左边常驻目录，右边一页一个词。
 * 翻页是 CSS 3D 合页 —— 右半那张纸绕书脊掀过去，纸背扫过目录并停在上面，
 * 底下就是下一页；往回翻时上一张纸从目录那边摆回来。
 *
 * 一张纸印两面：正面是这一开的右页（pages），背面是左页（backs）—— 翻过去
 * 以后朝上摊在左边。所以落定之后左边那张，永远是「刚翻过去那一张纸」的背面，
 * 照页码取 backs[index - 1]（比如翻过第一张，左边就是 backs[0]）。
 *
 * 翻过的纸不撤走（一直盖着，一页页叠上去），想再看目录得按页内那个「返回目录」
 * ——它把这叠纸摆走，目录重新露出来（uncovered）。往回翻一张、或者翻到别处，
 * 纸又自己摊回来。
 */

const TURN_MS = 620;

interface Turn {
  dir: "fwd" | "bwd";
  from: number;
  to: number;
}

export function WordbookFlip({
  children,
  pages,
  backs,
  index,
  onChange,
  onSwipePast,
  showNav = true,
  className,
  /** 每 +1 一次：把盖在目录上的纸摆回右边，让人重新看见目录。 */
  contentsSignal = 0,
}: {
  /** 左边的对象：整片左页（目录），由调用方给。 */
  children: ReactNode;
  /** 每一张纸正面的内容（这一开翻开时右边看的那个词）。 */
  pages: ReactNode[];
  /** 每一张纸背面的内容（翻过去以后摊在左边那个词）。缺了就还是白纸。 */
  backs?: ReactNode[];
  index: number;
  onChange: (index: number) => void;
  /** 在首页继续往回 / 末页继续往前时触发（用来进入复习）。 */
  onSwipePast?: (edge: "start" | "end") => void;
  showNav?: boolean;
  className?: string;
  contentsSignal?: number;
}) {
  const [turn, setTurn] = useState<Turn | null>(null);
  /** 「返回目录」把纸摆走了：左边暂时不摊纸，露出底下的目录。 */
  const [uncovered, setUncovered] = useState(false);
  const [flash, setFlash] = useState(0);
  const timersRef = useRef<number[]>([]);
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    startY: number;
    lastX?: number;
    lastY?: number;
  } | null>(null);

  const clearTimers = useCallback(() => {
    timersRef.current.forEach((timer) => window.clearTimeout(timer));
    timersRef.current = [];
  }, []);

  useEffect(() => clearTimers, [clearTimers]);

  const reducedMotion = () =>
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /** 落定：纸停在它该在的地方。左边摊不摊纸由 index / uncovered 推出来，这里只管收场。 */
  const settleTurn = useCallback((after?: () => void) => {
    const timer = window.setTimeout(() => {
      timersRef.current = [];
      setTurn(null);
      after?.();
    }, TURN_MS);
    timersRef.current = [timer];
  }, []);

  const flip = useCallback(
    (dir: "fwd" | "bwd") => {
      if (timersRef.current.length > 0) return;
      const from = index;
      const to = dir === "fwd" ? index + 1 : index - 1;
      if (to < 0 || to >= pages.length) {
        onSwipePast?.(dir === "fwd" ? "end" : "start");
        return;
      }
      if (reducedMotion()) {
        onChange(to);
        setUncovered(false);
        setFlash((value) => value + 1);
        return;
      }
      setTurn({ dir, from, to });
      onChange(to);
      settleTurn();
    },
    [index, onChange, onSwipePast, pages.length, settleTurn],
  );

  // 页内那个「返回目录」：把这叠纸摆走，目录重新露出来。
  const uncover = useCallback(() => {
    if (uncovered || index === 0 || timersRef.current.length > 0) return;
    if (reducedMotion()) {
      setUncovered(true);
      return;
    }
    const next: Turn = { dir: "bwd", from: index, to: index };
    setTurn(next);
    settleTurn(() => setUncovered(true));
  }, [index, settleTurn, uncovered]);

  const contentsRef = useRef(contentsSignal);
  useEffect(() => {
    if (contentsRef.current === contentsSignal) return;
    contentsRef.current = contentsSignal;
    uncover();
  }, [contentsSignal, uncover]);

  // 翻到别的地方（左右翻页、从目录跳页）纸就重新摊回来 —— 目录重新被盖上。
  // 顺带落一页轻响：隔了好几页跳过去时不做长距离翻飞。
  const landedRef = useRef(index);
  useEffect(() => {
    if (landedRef.current === index) return;
    landedRef.current = index;
    setUncovered(false);
    if (timersRef.current.length === 0) setFlash((value) => value + 1);
  }, [index]);

  // 掀着的那张纸的背面：正面是哪一页，背面就取哪一张。往回翻时纸是从左边
  // 摆回来的，它本来就是「上一张」（turn.from - 1）——「返回目录」那种原地
  // 摆回（from === to）也归这条。
  const turningBack = turn ? (turn.dir === "fwd" ? turn.from : turn.from - 1) : -1;
  const turnBack = turn ? (backs?.[turningBack] ?? null) : null;

  // 左边摊着的那张纸：刚落定的永远是 backs[index - 1]。掀着的那一张正在翻、
  // 而且翻的就是它（fwd 的纸背、uncover 的原地摆回）时不重复摆一遍 —— 底下
  // 那张正飞着，再摆一张一模一样的只会重影。
  const restBack = backs?.[index - 1] ?? null;
  const restVisible =
    !uncovered && index > 0 && restBack !== null && turningBack !== index - 1;

  return (
    <div
      className={cn("wordbook-flip", className)}
      data-turning={turn ? "" : undefined}
      onPointerDown={(event) => {
        dragRef.current = {
          pointerId: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
        };
      }}
      onPointerMove={(event) => {
        const drag = dragRef.current;
        if (!drag || drag.pointerId !== event.pointerId) return;
        // 手势在抬手时才结算：竖着划留给页内滚动，横着划才算翻页。
        drag.lastX = event.clientX;
        drag.lastY = event.clientY;
      }}
      onPointerUp={(event) => {
        const drag = dragRef.current;
        dragRef.current = null;
        if (!drag || drag.pointerId !== event.pointerId) return;
        const dx = (drag.lastX ?? drag.startX) - drag.startX;
        const dy = (drag.lastY ?? drag.startY) - drag.startY;
        if (Math.abs(dx) < 60 || Math.abs(dx) < Math.abs(dy) * 1.4) return;
        flip(dx < 0 ? "fwd" : "bwd");
      }}
      onPointerCancel={() => {
        dragRef.current = null;
      }}
    >
      <div className="wordbook-flip__book">
        {children}
        <article className="wordbook-leaf wordbook-leaf--right">
          <div
            className="wordbook-page-sheet wordbook-page-sheet--entry"
            key={flash}
          >
            {turn?.dir === "bwd" ? pages[turn.from] : pages[index]}
          </div>
        </article>

        {/* 已经翻过去、压在目录上的那些纸：最上面那张的背面朝上摊着
            （backs[index - 1]），写的是这一开左边的那个词。这是正文，
            不藏读屏 —— 左边这页里的按钮、边注都得摸得到。 */}
        {restVisible ? (
          <div className="wordbook-flip__sheet is-rest">
            <div className="wordbook-flip__face is-back">{restBack}</div>
          </div>
        ) : null}

        {turn ? (
          <div
            className={cn(
              "wordbook-flip__sheet",
              turn.dir === "fwd" ? "is-fwd" : "is-bwd",
            )}
          >
            <div className="wordbook-flip__face">
              <div className="wordbook-page-sheet">
                {turn.dir === "fwd" ? pages[turn.from] : pages[turn.to]}
              </div>
              <span className="wordbook-flip__sheen" aria-hidden="true" />
            </div>
            <div className="wordbook-flip__face is-back" aria-hidden="true">
              {turnBack}
              <span className="wordbook-flip__sheen is-back" />
            </div>
          </div>
        ) : null}

        {turn?.dir === "fwd" ? (
          <span className="wordbook-flip__cast" aria-hidden="true" />
        ) : null}

        <span className="wordbook-spine" aria-hidden="true" />

        {showNav ? (
          <>
            <button
              type="button"
              className="wordbook-flip__edge is-right"
              aria-label="下一页"
              onClick={() => flip("fwd")}
            />

            <div className="wordbook-flip__nav">
              <button
                type="button"
                onClick={() => flip("bwd")}
                aria-label="上一页"
              >
                ‹
              </button>
              <span className="wordbook-flip__count">
                {pages.length === 0 ? 0 : index + 1} / {pages.length}
              </span>
              <button
                type="button"
                onClick={() => flip("fwd")}
                aria-label="下一页"
              >
                ›
              </button>
            </div>
          </>
        ) : null}
      </div>
    </div>
  );
}
